[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "list by date"; fail=1; }
for bad in 2026/11/10 2026-13-01 2026-11-32 2026-00-10 2026-11-00; do
  o=$(BOOKINGS=$t bash src/list.sh "$bad" 2>/dev/null); rc=$?
  [ $rc = 2 ] && [ -z "$o" ] || { echo "list bad date exit $bad"; fail=1; }
done
e=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>&1 >/dev/null)
[ "$e" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date message"; fail=1; }
rm -f "$t"; exit $fail

